// Generates a realistic prop-photo fixture with a busy/cluttered background:
// a handheld electronic toy held in front of a cluttered desk with keyboard and shelf.
// Person-free / no human faces, compliant with hackathon test rules.
// Can be regenerated byte-for-byte:
//   npx tsx scripts/make-toy-fixture.ts
import { writeFileSync, mkdirSync } from "node:fs";
import { join } from "node:path";
import { pathToFileURL } from "node:url";
import { encodePng } from "./png";

const W = 480;
const H = 360;

function makeRng(seed: number): () => number {
  let s = seed >>> 0;
  return () => {
    s = (Math.imul(s, 1664525) + 1013904223) >>> 0;
    return s / 0x100000000;
  };
}

const mix = (a: readonly number[], b: readonly number[], t: number): [number, number, number] => [
  Math.round(a[0] + (b[0] - a[0]) * t),
  Math.round(a[1] + (b[1] - a[1]) * t),
  Math.round(a[2] + (b[2] - a[2]) * t),
];

export function drawToyDeskScene(): { width: number; height: number; rgba: Uint8Array } {
  const px = new Uint8Array(W * H * 4);
  const rng = makeRng(0x701);

  const put = (x: number, y: number, rgb: readonly number[], grain = true): void => {
    if (x < 0 || x >= W || y < 0 || y >= H) return;
    const o = (y * W + x) * 4;
    const jitter = grain ? Math.round(rng() * 6) - 3 : 0;
    px[o] = Math.max(0, Math.min(255, rgb[0] + jitter));
    px[o + 1] = Math.max(0, Math.min(255, rgb[1] + jitter));
    px[o + 2] = Math.max(0, Math.min(255, rgb[2] + jitter));
    px[o + 3] = 255;
  };

  const fillRect = (x0: number, y0: number, w: number, h: number, rgb: readonly number[], grain = true): void => {
    for (let y = y0; y < y0 + h; y++) {
      for (let x = x0; x < x0 + w; x++) {
        put(x, y, rgb, grain);
      }
    }
  };

  // 1. Wall background (neutral off-white / light beige)
  const WALL = [220, 215, 205] as const;
  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) {
      const vignette = 1 - 0.15 * ((x / W - 0.5) ** 2 + (y / H - 0.5) ** 2);
      put(x, y, [WALL[0] * vignette, WALL[1] * vignette, WALL[2] * vignette]);
    }
  }

  // 2. Shelf with books on top-right (x: 280..470, y: 30..110)
  const SHELF_WOOD = [110, 75, 45] as const;
  fillRect(280, 110, 190, 12, SHELF_WOOD, false);
  fillRect(280, 40, 190, 8, SHELF_WOOD, false);
  // Books on shelf
  const bookColors = [
    [160, 40, 40], [40, 70, 140], [50, 120, 60], [180, 130, 30],
    [120, 50, 120], [40, 140, 140], [150, 60, 30], [60, 60, 80],
  ] as const;
  let bx = 290;
  for (let i = 0; i < 8; i++) {
    const bw = 14 + (i % 3) * 4;
    const bh = 55 + (i % 4) * 5;
    fillRect(bx, 110 - bh, bw, bh, bookColors[i % bookColors.length]);
    bx += bw + 3;
  }

  // 3. Medal rack / board on top-left (x: 20..140, y: 30..100)
  fillRect(20, 30, 120, 6, [80, 80, 85], false); // bar
  const ribbonColors = [[180, 30, 30], [30, 60, 160], [200, 160, 30], [40, 130, 70]] as const;
  for (let i = 0; i < 4; i++) {
    const rx = 35 + i * 26;
    fillRect(rx, 36, 12, 38, ribbonColors[i]);
    // Medal circle
    const mcx = rx + 6;
    const mcy = 78;
    for (let my = mcy - 8; my <= mcy + 8; my++) {
      for (let mx = mcx - 8; mx <= mcx + 8; mx++) {
        if ((mx - mcx) ** 2 + (my - mcy) ** 2 <= 64) {
          put(mx, my, [210, 175, 40], false);
        }
      }
    }
  }

  // 4. Desk surface (lower half: y: 220..360)
  const DESK = [140, 110, 85] as const;
  fillRect(0, 220, W, H - 220, DESK);

  // 5. Cluttered desk items:
  // Keyboard (x: 40..250, y: 240..310, angled perspective)
  const KB_BASE = [50, 52, 58] as const;
  fillRect(40, 245, 210, 65, KB_BASE, false);
  // Keyboard keys grid
  for (let ky = 250; ky < 305; ky += 11) {
    for (let kx = 46; kx < 244; kx += 13) {
      fillRect(kx, ky, 10, 8, [85, 88, 96], false);
    }
  }
  // Mouse / pad (x: 270..340, y: 250..310)
  fillRect(265, 245, 75, 70, [35, 36, 40], false);
  fillRect(285, 260, 32, 45, [75, 78, 85], false);

  // 6. Hand arm entering from bottom-right (person's hand holding the toy)
  // Skin tones (arm: x: 260..380, y: 280..360)
  const SKIN = [215, 170, 140] as const;
  const SHIRT = [45, 70, 110] as const; // blue shirt cuff
  // Sleeve
  fillRect(290, 310, 120, 50, SHIRT);
  // Forearm / hand reaching up to center
  for (let y = 230; y < 330; y++) {
    const centerRx = 280 + (y - 230) * 0.3;
    const halfW = 28 + (y - 230) * 0.1;
    for (let x = Math.round(centerRx - halfW); x <= Math.round(centerRx + halfW); x++) {
      put(x, y, SKIN);
    }
  }

  // 7. Handheld Electronic Toy held in the center (x: 180..270, y: 130..250)
  const TOY_BODY = [35, 175, 210] as const; // vibrant cyan
  const TOY_ACCENT = [245, 170, 30] as const; // orange
  const TOY_SCREEN = [40, 55, 45] as const; // dark lcd screen
  const TOY_BTN = [225, 45, 60] as const; // red button

  const tx0 = 185;
  const ty0 = 135;
  const tw = 86;
  const th = 115;

  // Toy drop shadow on hand/desk
  for (let y = ty0 + 10; y <= ty0 + th + 10; y++) {
    for (let x = tx0 - 6; x <= tx0 + tw + 6; x++) {
      if (x < tx0 || x > tx0 + tw || y > ty0 + th) {
        const o = (y * W + x) * 4;
        if (o >= 0 && o < px.length) {
          px[o] = Math.round(px[o] * 0.65);
          px[o + 1] = Math.round(px[o + 1] * 0.65);
          px[o + 2] = Math.round(px[o + 2] * 0.65);
        }
      }
    }
  }

  // Toy body (rounded rectangle)
  for (let y = ty0; y < ty0 + th; y++) {
    for (let x = tx0; x < tx0 + tw; x++) {
      const isTopLeft = (x - tx0 < 4) || (y - ty0 < 4);
      const isBotRight = (tx0 + tw - x < 5) || (ty0 + th - y < 5);
      let col: readonly number[] = TOY_BODY;
      if (isTopLeft) col = mix(TOY_BODY, [255, 255, 255], 0.35);
      else if (isBotRight) col = mix(TOY_BODY, [0, 0, 0], 0.35);
      put(x, y, col);
    }
  }

  // Antenna on top
  fillRect(tx0 + 16, ty0 - 18, 6, 18, [180, 185, 190], false);
  // Red ball on antenna
  for (let y = ty0 - 24; y <= ty0 - 18; y++) {
    for (let x = tx0 + 14; x <= tx0 + 24; x++) {
      if ((x - (tx0 + 19)) ** 2 + (y - (ty0 - 21)) ** 2 <= 16) {
        put(x, y, [230, 40, 40], false);
      }
    }
  }

  // Screen
  fillRect(tx0 + 14, ty0 + 16, tw - 28, 42, TOY_SCREEN, false);
  fillRect(tx0 + 36, ty0 + 26, 12, 14, [120, 220, 110], false);
  fillRect(tx0 + 40, ty0 + 40, 4, 10, [120, 220, 110], false);

  // Directional D-pad & action buttons
  fillRect(tx0 + 16, ty0 + 74, 22, 7, [50, 52, 56], false);
  fillRect(tx0 + 23, ty0 + 66, 8, 23, [50, 52, 56], false);

  // Action buttons
  for (let my = ty0 + 68; my <= ty0 + 78; my++) {
    for (let mx = tx0 + 56; mx <= tx0 + 66; mx++) {
      if ((mx - (tx0 + 61)) ** 2 + (my - (ty0 + 73)) ** 2 <= 20) put(mx, my, TOY_BTN, false);
    }
  }
  for (let my = ty0 + 78; my <= ty0 + 88; my++) {
    for (let mx = tx0 + 68; mx <= tx0 + 78; mx++) {
      if ((mx - (tx0 + 73)) ** 2 + (my - (ty0 + 83)) ** 2 <= 20) put(mx, my, TOY_ACCENT, false);
    }
  }

  // Thumb overlapping front of toy (holding it)
  for (let y = ty0 + 85; y <= ty0 + 105; y++) {
    for (let x = tx0 + tw - 8; x <= tx0 + tw + 18; x++) {
      if ((x - (tx0 + tw + 4)) ** 2 + (y - (ty0 + 95)) ** 2 <= 140) {
        put(x, y, SKIN, false);
      }
    }
  }

  return { width: W, height: H, rgba: px };
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const { width, height, rgba } = drawToyDeskScene();
  const png = encodePng(width, height, rgba);
  const outPath = join(process.cwd(), "tests", "fixtures", "toy-desk-photo.png");
  mkdirSync(join(process.cwd(), "tests", "fixtures"), { recursive: true });
  writeFileSync(outPath, png);
  console.log(`Generated realistic cluttered fixture: ${outPath} (${width}x${height}, ${png.length} bytes)`);
}
